+    @* ───── STEP 2: Appointment Details ───── *@
+    @if (showStep2)
+    {
+        <fieldset class="mt-4">
+            <legend>Step 2 — Appointment Details</legend>
+
+            <div class="mb-3">
+                <label for="doctor" class="form-label">Preferred Doctor</label>
+                <InputSelect id="doctor" class="form-select"
+                             @bind-Value="Model.Doctor"
+                             @bind-Value:after="OnDoctorOrDateChanged">
+                    <option value="">-- Select --</option>
+                    @foreach (var doc in doctors)
+                    {
+                        <option value="@doc">@doc</option>
+                    }
+                </InputSelect>
+                <ValidationMessage For="() => Model.Doctor" />
+                @if (serverErrors.TryGetValue(nameof(Model.Doctor), out var docErr))
+                {
+                    <div class="validation-message">@docErr</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label for="appointmentDate" class="form-label">Date</label>
+                <InputDate id="appointmentDate" class="form-control"
+                           @bind-Value="Model.AppointmentDate"
+                           @bind-Value:after="OnDoctorOrDateChanged" />
+                <ValidationMessage For="() => Model.AppointmentDate" />
+            </div>
+
+            <div class="mb-3">
+                <label for="timeSlot" class="form-label">Time Slot</label>
+                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
+                    <option value="">-- Select --</option>
+                    @foreach (var slot in timeSlots)
+                    {
+                        <option value="@slot">@slot</option>
+                    }
+                </InputSelect>
+                <ValidationMessage For="() => Model.TimeSlot" />
+                @if (serverErrors.TryGetValue(nameof(Model.TimeSlot), out var slotErr))
+                {
+                    <div class="validation-message">@slotErr</div>
+                }
+            </div>
+
+            <div class="mb-3">
+                <label for="reason" class="form-label">Reason for Visit</label>
+                <InputTextArea id="reason" class="form-control" rows="3"
+                               @bind-Value="Model.ReasonForVisit" />
+                <ValidationMessage For="() => Model.ReasonForVisit" />
+            </div>
+
+            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
+                Back
+            </button>
+            <button type="button" class="btn btn-info me-2" @onclick="CheckAvailability"
+                    disabled="@isChecking">
+                @(isChecking ? "Checking…" : "Check Availability")
+            </button>
+            <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
+                Book Appointment
+            </button>
+        </fieldset>
+    }
+</EditForm>
+
+@if (booked)
+{
+    <div class="alert alert-success mt-4">
+        Appointment booked successfully for <strong>@Model.PatientName</strong>
+        with <strong>@Model.Doctor</strong> on @Model.AppointmentDate?.ToString("MMM dd, yyyy")
+        at @Model.TimeSlot.
+    </div>
+}
+
+@code {
+    private BookAppointmentModel Model { get; set; } = new();
+    private EditContext editContext = default!;
+    private ValidationMessageStore messageStore = default!;
+
+    private bool showStep2;
+    private bool isChecking;
+    private bool availabilityConfirmed;
+    private bool booked;
+
+    private List<string> doctors = [];
+    private List<string> timeSlots = [];
+    private Dictionary<string, string> serverErrors = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        editContext = new EditContext(Model);
+        messageStore = new ValidationMessageStore(editContext);
+        editContext.OnFieldChanged += (_, args) =>
+        {
+            // Clear server errors when the user edits the field
+            var fieldName = args.FieldIdentifier.FieldName;
+            if (serverErrors.Remove(fieldName))
+            {
+                messageStore.Clear(args.FieldIdentifier);
+                editContext.NotifyValidationStateChanged();
+            }
+            availabilityConfirmed = false;
+        };
+
+        doctors = await AppointmentSvc.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        messageStore.Clear();
+        serverErrors.Clear();
+
+        var valid = true;
+
+        if (string.IsNullOrWhiteSpace(Model.PatientName))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.PatientName)),
+                "Patient name is required.");
+            valid = false;
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.Email) ||
+            !System.ComponentModel.DataAnnotations.EmailAddressAttribute
+                .IsValid(typeof(string), Model.Email))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.Email)),
+                "A valid email is required.");
+            valid = false;
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.Phone))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.Phone)),
+                "Phone is required.");
+            valid = false;
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.InsuranceProvider)),
+                "Please select an insurance provider.");
+            valid = false;
+        }
+
+        editContext.NotifyValidationStateChanged();
+
+        if (valid)
+        {
+            showStep2 = true;
+        }
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        availabilityConfirmed = false;
+        Model.TimeSlot = string.Empty;
+        timeSlots = [];
+
+        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
+        {
+            timeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
+                Model.Doctor, Model.AppointmentDate.Value);
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        messageStore.Clear();
+        serverErrors.Clear();
+        availabilityConfirmed = false;
+        var valid = true;
+
+        // Client-side step-2 validation
+        if (string.IsNullOrWhiteSpace(Model.Doctor))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.Doctor)),
+                "Please select a doctor.");
+            valid = false;
+        }
+
+        if (!Model.AppointmentDate.HasValue)
+        {
+            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)),
+                "Date is required.");
+            valid = false;
+        }
+        else if (Model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.AppointmentDate)),
+                "Date must be in the future.");
+            valid = false;
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.TimeSlot)),
+                "Please select a time slot.");
+            valid = false;
+        }
+
+        if (string.IsNullOrWhiteSpace(Model.ReasonForVisit))
+        {
+            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)),
+                "Reason for visit is required.");
+            valid = false;
+        }
+        else if (Model.ReasonForVisit.Length > 500)
+        {
+            messageStore.Add(editContext.Field(nameof(Model.ReasonForVisit)),
+                "Reason must be 500 characters or fewer.");
+            valid = false;
+        }
+
+        editContext.NotifyValidationStateChanged();
+        if (!valid) return;
+
+        // Server-side validation
+        isChecking = true;
+        try
+        {
+            var result = await AppointmentSvc.ValidatePatientAsync(
+                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);
+
+            if (result.Count > 0)
+            {
+                foreach (var (field, error) in result)
+                {
+                    serverErrors[field] = error;
+                    messageStore.Add(editContext.Field(field), error);
+                }
+                editContext.NotifyValidationStateChanged();
+            }
+            else
+            {
+                availabilityConfirmed = true;
+            }
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        availabilityConfirmed = false;
+        serverErrors.Clear();
+        messageStore.Clear();
+        editContext.NotifyValidationStateChanged();
+    }
+
+    private void HandleSubmit()
+    {
+        if (availabilityConfirmed)
+        {
+            booked = true;
+        }
+    }
+}
+

